#![forbid(unsafe_code)]
// f32 can be accurate to 6–9 decimal places, allow the values to be truncated without warning.
#![allow(clippy::excessive_precision)]

//! High-order ambisonics to multi-channel (H2M) renderer and pre-computed gain matrices.
//!
//! Direct Rust port of `liboar/src/renderer/ear/h2m_rdr.c`.

use crate::common::definitions::{
    HighOrderAmbisonics, Layout, OarError, PlanarBufferMut, PlanarBufferRef,
    MAX_OUTPUT_CHANNEL_COUNT,
};
use crate::renderer::ear::channel_to_channel_renderer::IamfPredefinedSpLayout;
use crate::renderer::ear::matrix_renderer::{matrix_render, MatrixView};

/// High Order Ambisonics input configuration.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HoaWithLfeFlag {
    /// Order of the input ambisonic sound field.
    pub order: HighOrderAmbisonics,
    /// Flag indicating whether physical LFE channels should be active (true) or zeroed (false).
    pub lfe_on: bool,
}

/// Matrix entry table structure associating input HOA order with target loudspeaker layout (`h2m_rdr_t`).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct H2mRdr {
    /// Input Ambisonic order (`HighOrderAmbisonics`).
    pub in_order: HighOrderAmbisonics,
    /// Target output loudspeaker system (`BS2051`).
    pub out_system: Layout,
    /// Total number of physical output channels (including LFE slots).
    pub channels: usize,
    /// First LFE slot index (`-1` if none).
    pub lfe1: i32,
    /// Second LFE slot index (`-1` if none).
    pub lfe2: i32,
    /// Slice reference to precomputed gain table (`[f32; m * n]`).
    pub mat: &'static [f32],
    /// Number of matrix rows (Ambisonic channels + LFE inputs).
    pub m: usize,
    /// Number of matrix columns (non-LFE speaker outputs).
    pub n: usize,
}

