    #[gtest]
    fn render_h2m_lfe2_at_high_index_remaps_and_zeroes() {
        let h2m_matrix = H2mRdr {
            in_order: HighOrderAmbisonics::Zoa,
            out_system: Layout::LayoutA293,
            channels: 24,
            lfe1: 3,
            lfe2: 9,
            mat: &ZOA_BS9A3,
            m: 1,
            n: 22,
        };
        let in_channel = [1.0f32];
        let mut out_bufs = [[99.0f32; 1]; 24];

        let result = {
            let inputs = [&in_channel[..]];
            let mut out_slices: Vec<&mut [f32]> =
                out_bufs.iter_mut().map(|b| b.as_mut_slice()).collect();
            let inputs_buf = PlanarBufferRef::new(&inputs, 1, Samples::new(1).unwrap()).unwrap();
            let mut outputs_buf =
                PlanarBufferMut::new(&mut out_slices[..], 24, Samples::new(1).unwrap()).unwrap();
            element_renderer_render_h2m(&h2m_matrix, inputs_buf, &mut outputs_buf)
        };

        assert_ok!(result);
        expect_that!(out_bufs[3][0], eq(0.0));
        expect_that!(out_bufs[9][0], eq(0.0));
        expect_that!(out_bufs[0][0], near(0.09620442f32, EPSILON));
        expect_that!(out_bufs[23][0], near(0.21963451f32, EPSILON));
    }
